 void inspectTranslationResume(boolean body){String workflow=body?bookTranslation:translation;if(workflow.isEmpty()){showActionMessage("استئناف الترجمة","اختر كتابًا له مسار ترجمة محفوظ أولًا.");return;}run("فحص إتاحة الاستئناف",()->{JSONObject response=get("/v1/translations/"+workflow);updateTranslationRetry(body,response);boolean ready=response.optJSONObject("resume_request")!=null;runOnUiThread(()->showActionMessage("استئناف الترجمة",ready?"طلب الاستئناف أصبح متاحًا. استخدم زر الاستئناف بعد تحديث الحالة.":"الخادم لم يوفر طلب الاستئناف الأصلي لهذا المسار. النتائج المحفوظة باقية؛ يلزم تحديث الخادم أو استعادة طلب التشغيل قبل الاستئناف. هذا الزر يفحص الحالة ولا يعيد تشغيل الخادم."));return "تم فحص الحالة دون تشغيل ترجمة جديدة.";});}
 void retryTranslation(boolean body){String old=body?bookTranslation:translation;if(old.isEmpty())return;String cid=course.getText().toString().trim();run("استئناف ترجمة "+(body?"متن الكتاب":"الملحق"),()->{JSONObject status=get("/v1/translations/"+old);if(!translationCanResume(status))throw new IOException("هذا المسار لم يعد متوقفًا؛ تم تحديث حالته.");JSONObject original=status.optJSONObject("resume_request");if(original==null)throw new IOException("طلب الترجمة الأصلي غير متاح؛ يلزم تحديث الخادم للاستئناف الآمن.");if(!cid.equals(status.optString("course_id",cid)))throw new IOException("المسار لا ينتمي إلى الكتاب المختار.");JSONObject request=new JSONObject(original.toString());request.put("resume_from_workflow_id",old);request.put("force_regenerate",false);applyTranslationProviderChoice(request);String next=req("POST","/v1/courses/"+cid+"/translations",request).getString("workflow_id");if(body)bookTranslation=next;else translation=next;persistProgress();progressWatching=true;refreshStatusesBlocking();return "حُفظ المسار الجديد؛ سيستأنف من النتائج المحفوظة.";});}
