 String base(){String configured=configuredBase();return EndpointRouting.candidates(configured).contains(activeEndpoint)?activeEndpoint:configured;}
 void saveEndpoint(){final String next;try{next=EndpointRouting.normalize(url.getText().toString());}catch(IllegalArgumentException e){showActionMessage("عنوان الخادم",e.getMessage());return;}Runnable save=()->{if(!EndpointRouting.sameHost(configuredBase(),next))p.edit().remove("api_token_ciphertext").apply();p.edit().putString("api_base_url",next).apply();activeEndpoint="";endpointCheckedAt=0;url.setText(next);updateConnectionLabel("حُفظ العنوان؛ افحص الاتصال.");};if(!EndpointRouting.sameHost(configuredBase(),next)){new AlertDialog.Builder(this).setTitle("تغيير الخادم").setMessage("سيُطلب رمز وصول جديد للخادم الجديد. لن يُرسل الرمز الحالي إليه. معرّفات العمل المحفوظة ستبقى.").setPositiveButton("حفظ",(d,w)->save.run()).setNegativeButton("إلغاء",null).show();}else save.run();}
