 boolean healthProbe(String origin)throws IOException{HttpURLConnection c=(HttpURLConnection)new URL(origin+"/health").openConnection();try{c.setInstanceFollowRedirects(false);c.setConnectTimeout(4000);c.setReadTimeout(4000);return c.getResponseCode()==200;}finally{c.disconnect();}}
 synchronized String readyBase(boolean force,String avoid)throws IOException{String configured=configuredBase();if(!force&&System.currentTimeMillis()-endpointCheckedAt<30000&&EndpointRouting.candidates(configured).contains(activeEndpoint))return activeEndpoint;String preferred=activeEndpoint;List<String> choices=EndpointRouting.candidates(configured);if(avoid!=null){choices.remove(avoid);if(choices.isEmpty())throw new IOException("لا يوجد مسار بديل موثوق للخادم.");preferred=choices.get(0);}final String rejected=avoid;String chosen=EndpointRouting.select(configured,preferred,origin->!origin.equals(rejected)&&healthProbe(origin));activeEndpoint=chosen;endpointCheckedAt=System.currentTimeMillis();updateConnectionLabel("متصل بالخادم · المنفذ "+(URI.create(chosen).getPort()==-1?443:URI.create(chosen).getPort()));return chosen;}

