 String read(InputStream in)throws Exception{if(in==null)return"";ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] x=new byte[8192];int n;while((n=in.read(x))>0)b.write(x,0,n);return b.toString("UTF-8");}
 JSONObject get(String path)throws Exception{return req("GET",path,null);}
 static class HttpFailure extends IOException{final int code;HttpFailure(int c,String body){super("HTTP "+c+" "+body);code=c;}}
 JSONObject requestOnce(String origin,String method,String path,JSONObject body,String token)throws Exception{
  if(!path.startsWith("/")||path.startsWith("//"))throw new IOException("مسار طلب غير صالح.");
  HttpURLConnection c=(HttpURLConnection)new URL(origin+path).openConnection();
  try{c.setInstanceFollowRedirects(false);c.setRequestMethod(method);c.setConnectTimeout(10000);c.setReadTimeout("GET".equals(method)?120000:1800000);c.setRequestProperty("Accept","application/json");c.setRequestProperty("Authorization","Bearer "+token);
   if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes("UTF-8"));}}
   int code=c.getResponseCode();String value=read(code>=400?c.getErrorStream():c.getInputStream());
   if(code<200||code>=300)throw new HttpFailure(code,value);return new JSONObject(value);
  }finally{c.disconnect();}
 }
 JSONObject req(String method,String path,JSONObject body)throws Exception{
  String token=ensureApiToken();String origin=readyBase(false,null);
  for(int auth=0;auth<2;auth++){try{return requestOnce(origin,method,path,body,token);}
   catch(HttpFailure e){if(e.code==401&&auth==0){p.edit().remove("api_token_ciphertext").apply();token=ensureApiToken();continue;}
    if("GET".equals(method)&&(e.code==502||e.code==503||e.code==504)){origin=readyBase(true,origin);return requestOnce(origin,method,path,body,token);}throw e;}
   catch(IOException e){if("GET".equals(method)){origin=readyBase(true,origin);return requestOnce(origin,method,path,body,token);}endpointCheckedAt=0;throw new IOException("انقطع الرد؛ لم يُعد التطبيق إرسال طلب التشغيل. حدّث الحالة أولًا قبل محاولة جديدة.",e);}
  }throw new IOException("لم يقبل الخادم رمز الوصول.");
 }

