 void editCourseName(boolean create){EditText name=new EditText(this);name.setHint("اسم المقرر");if(!create)name.setText(p.getString("course_name",course.getText().toString()));new AlertDialog.Builder(this).setTitle(create?"إنشاء مقرر جديد":"تعديل اسم المقرر").setView(name).setPositiveButton("حفظ",(d,w)->{final String value=name.getText().toString().trim(),cid=course.getText().toString().trim();if(value.isEmpty()){Toast.makeText(this,"اكتب اسمًا للمقرر",Toast.LENGTH_LONG).show();return;}run("حفظ المقرر",()->{JSONObject result=req(create?"POST":"PATCH",create?"/v1/courses":"/v1/courses/"+URLEncoder.encode(cid,"UTF-8"),new JSONObject().put("name",value));runOnUiThread(()->{if(create)switchCourse(result);else{p.edit().putString("course_name",result.optString("name")).apply();renderScreen(0);}});return "تم حفظ اسم المقرر";});}).setNegativeButton("إلغاء",null).show();}
