  count.run();search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence query,int start,int before,int count){String value=query.toString().trim().toLowerCase(Locale.ROOT);for(int i=0;i<items.size();i++)cards.get(i).setVisibility((items.get(i).optString("display_name")+" "+items.get(i).optString("title")+" "+items.get(i).optString("source_filename")+" "+items.get(i).optString("book_id")).toLowerCase(Locale.ROOT).contains(value)?View.VISIBLE:View.GONE);}public void afterTextChanged(android.text.Editable s){}});
  AlertDialog picker=new AlertDialog.Builder(this).setTitle("مكتبة الكتب").setView(panel).setPositiveButton("استخدام الكتب المختارة",null).setNegativeButton("إلغاء",null).create();
