 String compositionKey(String cid,String bid){return "composition:"+cid+":"+bid;} String courseRoleKey(String cid,String bid){return "course-role:"+cid+":"+bid;} String idsFromMap(String raw){try{JSONArray a=new JSONArray();JSONObject m=new JSONObject(raw);Iterator<String> k=m.keys();while(k.hasNext())a.put(k.next());return a.toString().replace("[","").replace("]","").replace("\"","");}catch(Exception e){return "";}} void saveCurrentComposition(){if(course==null||book==null||suppWorkflows==null)return;String cid=course.getText().toString().trim(),bid=book.getText().toString().trim();if(cid.isEmpty()||bid.isEmpty())return;String map=suppWorkflows.getText().toString().trim();if(map.isEmpty())map="{}";p.edit().putString(compositionKey(cid,bid),map).apply();}
