 void loadProgress(){try{String raw=p.getString(progressKey(),"");JSONObject j=raw.isEmpty()?new JSONObject():new JSONObject(raw);boolean same=ingest.equals(p.getString("i",""))&&BookIdentity.sameContext(course.getText().toString().trim(),book.getText().toString().trim(),p.getString("course",""),p.getString("book",""));index=j.optString("index",same?p.getString("x",""):"");qa=j.optString("qa",same?p.getString("q",""):"");approved=j.optString("approved",same?p.getString("a",""):"");translation=j.optString("translation",same?p.getString("tr",""):"");bookTranslation=j.optString("book_translation",same?p.getString("btr",""):"");audio=j.optString("audio",same?p.getString("mp3",""):"");}catch(Exception ignored){index="";qa="";approved="";translation="";bookTranslation="";audio="";}}
 String statusName(String raw){switch(raw){case "RUNNING":return "قيد التنفيذ";case "PAUSED":return "متوقفة مؤقتًا";case "PAUSE_REQUESTED":return "بانتظار نقطة الحفظ للإيقاف المؤقت";case "COMPLETED":return "مكتملة";case "FAILED":return "فشلت";case "CANCELED":return "أُلغيت";case "TERMINATED":return "أُوقفت";case "TIMED_OUT":return "انتهت المهلة";case "CONTINUED_AS_NEW":return "مستمرة";default:return raw.isEmpty()?"غير معروف":raw;}}
