 String mainTranslationWorkflow(){return translation.isEmpty()?bookTranslation:translation;}
 void resolveLegacyBookIdentity()throws Exception{
  String cid=course.getText().toString().trim(),bid=book.getText().toString().trim();
  if(newPdfSelected||bid.matches("book-[0-9a-f]{24}"))return;
  JSONArray books=get("/v1/courses/"+URLEncoder.encode(cid,"UTF-8")+"/books").optJSONArray("books");
  JSONObject match=null;int matches=0;
  if(books!=null)for(int i=0;i<books.length();i++){
   JSONObject item=books.getJSONObject(i);String stable=BookIdentity.publicId(item.optString("book_id"),item.optString("file_sha256"));
   if(bid.equals(item.optString("book_id"))||bid.equals(item.optString("artifact_book_id"))){match=item;matches++;item.put("book_id",stable);}
  }
  if(matches>1)throw new IOException("اختر الكتاب من المكتبة لتحديد بصمته الصحيحة.");
  if(match==null)return;
  final JSONObject resolved=match;final String stable=match.getString("book_id");
  if(stable.equals(bid))return;
  CountDownLatch latch=new CountDownLatch(1);runOnUiThread(()->{selectedBook=resolved;book.setText(stable);title.setText(bookDisplayTitle(resolved));p.edit().putString("book",stable).putString("title",title.getText().toString()).apply();if(stageBookLabel!=null)stageBookLabel.setText("الكتاب الحالي: "+bookDisplayTitle(resolved));latch.countDown();});
  if(!latch.await(10,TimeUnit.SECONDS))throw new IOException("تعذر ربط الكتاب المحفوظ ببصمته.");
  index="";qa="";translation="";bookTranslation="";audio="";approved="";runOnUiThread(this::clearAudioSelection);
 }
 void refreshStatusesBlocking()throws Exception{
  resolveLegacyBookIdentity();
  String cid=course.getText().toString().trim(),bid=book.getText().toString().trim();
  if(cid.isEmpty()||bid.isEmpty())throw new IOException("أدخل معرّف المقرر والكتاب.");
  JSONObject registry=get("/v1/courses/"+cid+"/books/"+bid+"/progress");JSONObject stages=registry.optJSONObject("stages");if(stages==null)stages=new JSONObject();
  applyStageRegistry(stages);
  persistProgress();
  String[] ids={ingest,index,qa,mainTranslationWorkflow(),audio};String[] routes={"/v1/ingestions/","/v1/indexings/","/v1/course-qa/","/v1/translations/","/v1/audio/"};
  String[] labels={"رفع الملف و OCR","الفهرسة","الدروس والأسئلة","الترجمة","الصوت"};
  for(int i=0;i<ids.length;i++){
   if(ids[i].isEmpty()){if(i==1&&!approved.isEmpty())setStage(i,"المخطط معتمد","قراءة الكتاب مقسّمة إلى دروس؛ الفهرسة غير مطلوبة لهذا الناتج.",100);else setStage(i,"لم تبدأ","لم يُسجّل تشغيل لهذه المرحلة بعد.",0);continue;}
   try{JSONObject stageResult=get(routes[i]+ids[i]+(i==0?"?recovery_course_id="+URLEncoder.encode(cid,"UTF-8"):i==2?"?recovery_course_id="+URLEncoder.encode(cid,"UTF-8")+"&recovery_book_id="+URLEncoder.encode(bid,"UTF-8"):""));renderWorkflow(i,labels[i],stageResult);if(i==3)renderTranslationTracks(stageResult);}
   catch(Exception e){setStage(i,"تعذر التحديث",e.getMessage(),-1);if(i==3)renderTranslationTracks(null);}
  }
  if(translation.isEmpty()&&!bookTranslation.isEmpty()){try{renderBodyTranslationTrack(get("/v1/translations/"+bookTranslation));}catch(Exception e){setTranslationTrack(true,"تعذر التحديث",-1,e.getMessage());}}
  if(state!=null)runOnUiThread(()->state.setText(ids()));
 }
