  if(ingest.isEmpty()){run("معاينة النص",()->{refreshStatusesBlocking();if(ingest.isEmpty())throw new IOException("اختر كتابًا محفوظًا أولًا.");runOnUiThread(this::previewText);return "تم استعادة الكتاب.";});return;}
