 void loadOcrPage(int offset,TextView body,TextView counter,Button prev,Button next,int size){io.execute(()->{try{String path="/v1/ingestions/"+ingest+"/text?course_id="+URLEncoder.encode(course.getText().toString().trim(),"UTF-8")+"&offset="+offset+"&limit=100";JSONObject j=get(path);JSONArray blocks=j.getJSONArray("blocks");StringBuilder out=new StringBuilder();for(int i=0;i<blocks.length();i++){JSONObject b=blocks.getJSONObject(i);JSONArray ps=b.optJSONArray("pages");out.append("صفحة ").append(ps==null?"—":ps.toString()).append(" · ").append(b.optString("type")).append("\n").append(b.optString("text")).append("\n\n");}int total=j.optInt("total_blocks");runOnUiThread(()->{body.setText(out.length()==0?"لا توجد مقاطع في هذا النطاق.":out.toString());body.setTextSize(size);counter.setText("المقاطع "+(offset+1)+"–"+Math.min(offset+blocks.length(),total)+" من "+total);prev.setEnabled(offset>0);next.setEnabled(offset+blocks.length()<total);});}catch(Exception e){runOnUiThread(()->body.setText("تعذر تحميل النص: "+e.getMessage()));}});}

