 File downloadBookPdf()throws Exception{
  String cId=URLEncoder.encode(course.getText().toString().trim(),"UTF-8"),bId=URLEncoder.encode(book.getText().toString().trim(),"UTF-8");
  HttpURLConnection c=(HttpURLConnection)new URL(readyBase(false,null)+"/v1/courses/"+cId+"/books/"+bId+"/source").openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(60000);String token=apiToken();if(!token.isEmpty())c.setRequestProperty("Authorization","Bearer "+token);
  int code=c.getResponseCode();if(code<200||code>=300){String err=read(c.getErrorStream());c.disconnect();throw new IOException("HTTP "+code+" "+err);}
  File f=new File(getCacheDir(),"book2course-preview.pdf");try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(f)){byte[]buf=new byte[65536];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}finally{c.disconnect();}return f;
 }
 void showPdf(File f,int initialPage){
  try{android.os.ParcelFileDescriptor fd=android.os.ParcelFileDescriptor.open(f,android.os.ParcelFileDescriptor.MODE_READ_ONLY);android.graphics.pdf.PdfRenderer renderer=new android.graphics.pdf.PdfRenderer(fd);int count=renderer.getPageCount();final int[] current={Math.max(0,Math.min(initialPage,count-1))};
   LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(8,8,8,8);TextView counter=text("",14,ink,true);panel.addView(counter);ZoomImage image=new ZoomImage();image.setBackgroundColor(0xffeeeeea);ScrollView sc=new ScrollView(this);sc.addView(image);panel.addView(sc,new LinearLayout.LayoutParams(-1,0,1));SeekBar pagesBar=new SeekBar(this);pagesBar.setMax(Math.max(0,count-1));pagesBar.setProgress(current[0]);panel.addView(pagesBar);LinearLayout nav=new LinearLayout(this);Button prev=btn("السابق",()->{}),next=btn("التالي",()->{});nav.addView(prev,new LinearLayout.LayoutParams(0,56,1));nav.addView(next,new LinearLayout.LayoutParams(0,56,1));panel.addView(nav);
   AlertDialog dialog=new AlertDialog.Builder(this).setTitle(title.getText().toString()).setView(panel).setPositiveButton("إغلاق",null).create();Runnable[] render={null};render[0]=()->{try{android.graphics.pdf.PdfRenderer.Page page=renderer.openPage(current[0]);int w=Math.min(1800,Math.max(1000,getResources().getDisplayMetrics().widthPixels*2));int h=Math.max(1,(int)((float)page.getHeight()/page.getWidth()*w));android.graphics.Bitmap bmp=android.graphics.Bitmap.createBitmap(w,h,android.graphics.Bitmap.Config.ARGB_8888);page.render(bmp,null,null,android.graphics.pdf.PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);page.close();android.graphics.Bitmap old=image.getBitmap();image.setImageBitmap(bmp);if(old!=null&&old!=bmp)old.recycle();image.resetZoom();counter.setText("صفحة "+(current[0]+1)+" من "+count);pagesBar.setProgress(current[0]);prev.setEnabled(current[0]>0);next.setEnabled(current[0]+1<count);p.edit().putInt("reader_page:"+book.getText().toString().trim(),current[0]).apply();}catch(OutOfMemoryError oom){add("الصفحة أكبر من ذاكرة العرض المتاحة على هذا الجهاز.");}catch(Exception e){add("تعذر رسم الصفحة: "+e.getMessage());}};
   prev.setOnClickListener(v->{if(current[0]>0){current[0]--;render[0].run();}});next.setOnClickListener(v->{if(current[0]+1<count){current[0]++;render[0].run();}});pagesBar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean user){}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){current[0]=b.getProgress();render[0].run();}});dialog.setOnDismissListener(d->{try{renderer.close();fd.close();}catch(Exception ignored){}});dialog.show();render[0].run();
  }catch(Exception e){add("تعذر عرض PDF: "+e.getMessage());}
 }
 class ZoomImage extends ImageView{private final Matrix matrix=new Matrix();private final ScaleGestureDetector scaleDetector;private float scale=1f,lastX,lastY;private boolean dragging;ZoomImage(){super(MainActivity.this);setScaleType(ScaleType.MATRIX);scaleDetector=new ScaleGestureDetector(MainActivity.this,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){scale=Math.max(1f,Math.min(5f,scale*d.getScaleFactor()));matrix.setScale(scale,scale,d.getFocusX(),d.getFocusY());setImageMatrix(matrix);return true;}});setOnTouchListener((v,e)->{scaleDetector.onTouchEvent(e);if(e.getPointerCount()==1&&!scaleDetector.isInProgress()){if(e.getAction()==MotionEvent.ACTION_DOWN){lastX=e.getX();lastY=e.getY();dragging=true;}else if(e.getAction()==MotionEvent.ACTION_MOVE&&dragging&&scale>1){matrix.postTranslate(e.getX()-lastX,e.getY()-lastY);setImageMatrix(matrix);lastX=e.getX();lastY=e.getY();}else if(e.getAction()==MotionEvent.ACTION_UP)dragging=false;}return true;});}void resetZoom(){scale=1f;matrix.reset();setImageMatrix(matrix);}android.graphics.Bitmap getBitmap(){android.graphics.drawable.Drawable d=getDrawable();return d instanceof android.graphics.drawable.BitmapDrawable?((android.graphics.drawable.BitmapDrawable)d).getBitmap():null;}}

