 void loadAudioTracks(){audioListStatus.setText("يحمّل مجلد صوت المقرر…");final String requestedCourse=course.getText().toString().trim();monitorIo.execute(()->{try{JSONObject folder=get("/v1/courses/"+URLEncoder.encode(requestedCourse,"UTF-8")+"/audio");JSONArray workflows=folder.optJSONArray("workflows");runOnUiThread(()->{if(!requestedCourse.equals(course.getText().toString().trim()))return;if(workflows==null||workflows.length()==0){JSONArray saved=folder.optJSONArray("tracks");if(saved!=null&&saved.length()>0){applySavedAudioFolder(requestedCourse,folder);return;}clearAudioSelection();audioZipPath="";audioListStatus.setText("المقرر: "+folder.optString("course_name",requestedCourse)+" · لا توجد ملفات صوت محفوظة بعد.");return;}if(workflows.length()==1){applyAudioFolder(requestedCourse,folder,workflows.optJSONObject(0));return;}String[] choices=new String[workflows.length()];int preferred=0;for(int i=0;i<choices.length;i++){JSONObject w=workflows.optJSONObject(i);JSONArray tracks=w.optJSONArray("tracks");choices[i]="إنتاج "+(i+1)+" · "+statusName(w.optString("status"))+" · "+(tracks==null?0:tracks.length())+" ملف محفوظ";if(audio.equals(w.optString("workflow_id")))preferred=i;}audioListStatus.setText("اختر نسخة إنتاج واحدة للمقرر؛ لن تُخلط الملفات بين النسخ.");new AlertDialog.Builder(this).setTitle(folder.optString("course_name",requestedCourse)).setSingleChoiceItems(choices,preferred,(d,n)->{applyAudioFolder(requestedCourse,folder,workflows.optJSONObject(n));d.dismiss();}).setNegativeButton("إغلاق",null).show();});}catch(Exception e){runOnUiThread(()->audioListStatus.setText("تعذر تحديث الصوت: "+(e.getMessage()==null?"تحقق من الاتصال ثم أعد المحاولة":e.getMessage())));}});}
 void applyAudioFolder(String requestedCourse,JSONObject folder,JSONObject workflow){if(workflow==null||!requestedCourse.equals(course.getText().toString().trim()))return;clearAudioSelection();audioBrowseWorkflow=workflow.optString("workflow_id");audioZipPath=workflow.optString("zip_url");ArrayList<String> labels=new ArrayList<>();JSONArray tracks=workflow.optJSONArray("tracks");if(tracks!=null)for(int i=0;i<tracks.length();i++){JSONObject x=tracks.optJSONObject(i);if(x==null)continue;try{x.put("_language",workflow.optString("language"));x.put("_source_kind",workflow.optString("kind"));if(workflow.optJSONObject("source_identity")!=null)x.put("_source_identity",workflow.getJSONObject("source_identity"));}catch(JSONException ignored){}audioEntries.add(x);labels.add(x.optString("display_filename",x.optString("filename","مقطع"))+" · "+x.optString("title"));}ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,labels);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);audioSelection.setAdapter(adapter);audioListStatus.setText("مجلد: "+folder.optString("course_name",requestedCourse)+" · ملفات محفوظة: "+audioEntries.size()+" · "+statusName(workflow.optString("status"))+(labels.isEmpty()?" · لم يكتمل ملف بعد":""));}
