 JSONObject committedTranslationRef(String id)throws Exception{if(id.isEmpty())throw new IOException("استأنف الترجمة بعد اعتماد التعديل وانتظر ناتجًا محفوظًا جديدًا قبل إعادة الصوت.");JSONObject status=get("/v1/translations/"+id);if(!"COMPLETED".equals(status.optString("status"))||translationHasGaps(status))throw new IOException("ترجمة الدرس لم تكتمل؛ استأنف الأجزاء الناقصة قبل إعادة الصوت.");return status.getJSONObject("result").getJSONObject("artifact");}
 void regenerateSelectedLesson(){int selected=selectedAudioIndex();if(selected<0||selected>=audioEntries.size()){showActionMessage("إعادة صوت درس","اختر ملف درس من قائمة الصوت أولًا.");return;}JSONObject track=audioEntries.get(selected);String lessonId=track.optString("lesson_id");if(lessonId.isEmpty()){showActionMessage("إعادة صوت درس","الملف ليس تابعًا لدرس منفرد؛ اختر صوت درس أو ملحقه.");return;}final String cid=course.getText().toString().trim(),bid=book.getText().toString().trim();new AlertDialog.Builder(this).setTitle("إعادة صوت هذا الدرس وملحقه فقط").setMessage("بعد تعديل ترجمة الدرس واعتمادها، استأنف الترجمة أولًا حتى يُحفظ ناتجها الجديد. سيُستخدم المصدر المحفوظ الحالي للكتاب المحدد، وتظل ملفات الصوت القديمة محفوظة.").setPositiveButton("فحص المصادر الحالية",(d,w)->monitorIo.execute(()->{try{refreshStatusesBlocking();if(!cid.equals(course.getText().toString().trim())||!bid.equals(book.getText().toString().trim()))throw new IOException("تغير الكتاب المحدد؛ اختر الدرس مجددًا.");if(ingest.isEmpty()||approved.isEmpty())throw new IOException("اختر الكتاب المصدر لهذا الدرس وحدّث حالته ومخططه المعتمد.");JSONObject outline=get("/v1/ingestions/"+ingest+"/outline").getJSONObject("outline");boolean found=false;JSONArray modules=outline.optJSONArray("modules");if(modules!=null)for(int m=0;m<modules.length();m++){JSONArray lessons=modules.optJSONObject(m).optJSONArray("lessons");if(lessons!=null)for(int n=0;n<lessons.length();n++)if(lessonId.equals(lessons.optJSONObject(n).optString("lesson_id")))found=true;}if(!found)throw new IOException("الدرس لا ينتمي لمخطط الكتاب المحدد؛ اختر الكتاب الصحيح.");JSONObject original=get("/v1/ingestions/"+ingest).getJSONObject("result").getJSONObject("parsed_book").getJSONObject("ref");JSONObject audioIdentity=track.optJSONObject("_source_identity");if(audioIdentity==null||!original.optString("sha256").equals(audioIdentity.optString("source_parsed_sha256")))throw new IOException("بصمة مصدر الصوت لا تطابق الكتاب المحدد؛ اختر مصدره الصحيح قبل إعادة الدرس.");String language=track.optString("_language");if(!"ar".equals(language)&&!"en".equals(language))throw new IOException("لغة الصوت الأصلي غير متاحة؛ حدّث قائمة الصوت.");boolean isCourse="course".equals(track.optString("_source_kind"));String planPath="/v1/ingestions/"+ingest+"/processing-plan?course_id="+URLEncoder.encode(cid,"UTF-8")+"&target_output=audio&target_language="+language+"&content_kind="+(isCourse?"course":"book")+"&include_questions="+(isCourse?"true":"false");JSONObject plan=get(planPath).getJSONObject("plan");if(plan.optBoolean("requires_user_input"))throw new IOException("لغة المصدر تحتاج تأكيدًا؛ حدّدها في إعداد المراحل أولًا.");boolean translated=planNeedsTranslation(plan);JSONObject source=original,qaRef=null,bodyRef=null;boolean partialQA=false;if(isCourse){if(qa.isEmpty())throw new IOException("الملحق يحتاج نتيجة أسئلة محفوظة للكتاب المحدد.");JSONObject qaState=get("/v1/course-qa/"+qa);JSONObject savedQA=qaState.optJSONObject("result");if(savedQA==null||savedQA.optJSONObject("artifact")==null)throw new IOException("انتظر حفظ نتيجة أسئلة موثقة لهذا الكتاب قبل إعادة صوت الملحق.");partialQA=!"COMPLETED".equals(qaState.optString("status"));qaRef=savedQA.getJSONObject("artifact");source=qaRef;if(translated){source=committedTranslationRef(translation);bodyRef=committedTranslationRef(bookTranslation);}}else if(translated)source=committedTranslationRef(bookTranslation.isEmpty()?translation:bookTranslation);JSONObject request=new JSONObject().put("source_artifact_ref",source).put("source_kind",isCourse?"course":"book").put("language",language).put("approved_outline_ref",new JSONObject(approved)).put("source_book_ref",original).put("lesson_ids",new JSONArray().put(lessonId)).put("include_extra_scopes",false).put("include_summaries",summaryToggle!=null&&summaryToggle.isChecked());if(isCourse){request.put("source_qa_artifact_ref",qaRef);request.put("allow_partial_qa",partialQA);if(bodyRef!=null)request.put("source_book_translation_ref",bodyRef);}else request.put("book_audio_layout","lessons");final String reference=source.optString("uri")+"\nSHA-256: "+source.optString("sha256");runOnUiThread(()->new AlertDialog.Builder(this).setTitle("اعتماد مصدر إعادة الصوت").setMessage("الدرس: "+track.optString("title",lessonId)+"\nالمصدر المحفوظ الحالي:\n"+reference+"\nهل هذا ناتج الترجمة الحالي الذي تريد قراءته؟").setPositiveButton("إعادة هذا الدرس",(confirm,n)->monitorIo.execute(()->{try{if(!cid.equals(course.getText().toString().trim())||!bid.equals(book.getText().toString().trim()))throw new IOException("تغير الكتاب المحدد؛ لم يبدأ الطلب.");JSONObject result=req("POST","/v1/courses/"+URLEncoder.encode(cid,"UTF-8")+"/audio/regenerate",request);showActionMessage("إعادة صوت درس","بدأت نسخة صوت جديدة لهذا الدرس فقط. حدّث قائمة الصوت واختر نسخة الإنتاج الجديدة؛ الملفات السابقة محفوظة.");}catch(Exception e){showActionMessage("تعذر إعادة صوت الدرس",e.getMessage());}})).setNegativeButton("إلغاء",null).show());}catch(Exception e){showActionMessage("تعذر تجهيز إعادة الصوت",e.getMessage());}})).setNegativeButton("إلغاء",null).show();}
 int selectedAudioIndex(){return audioSelection==null?0:audioSelection.getSelectedItemPosition();}
 String audioPath(int index)throws Exception{JSONObject x=audioEntries.get(index);String savedPath=x.optString("download_path","");if(x.optBoolean("historical")&&!savedPath.isEmpty()){if(!savedPath.startsWith("/v1/courses/")||savedPath.contains(".."))throw new IOException("مسار الصوت المحفوظ غير صالح.");return savedPath;}if(x.has("download_url"))return x.getString("download_url");return "book".equals(x.optString("track_id"))?"/v1/audio/"+audioBrowseWorkflow+"/file":"/v1/audio/"+audioBrowseWorkflow+"/tracks/"+URLEncoder.encode(x.getString("track_id"),"UTF-8");}
