 void applyAudioSpeed(){if(player==null||!player.isPlaying()&&player.getCurrentPosition()<0||audioSpeed==null)return;try{float[] speeds={0.75f,1f,1.25f,1.5f,1.75f,2f};player.setPlaybackParams(new PlaybackParams().setSpeed(speeds[audioSpeed.getSelectedItemPosition()]));}catch(Exception ignored){}}
 void playTrack(int index){if(index<0||index>=audioEntries.size()){add("اختر مقطعًا صوتيًا جاهزًا أولًا");return;}stopAudio();activeTrack=index;try{player=new MediaPlayer();String path=audioPath(index);Map<String,String> headers=new HashMap<>();String token=apiToken();if(!token.isEmpty())headers.put("Authorization","Bearer "+token);player.setDataSource(this,Uri.parse(base()+path),headers);player.setOnPreparedListener(mp->{int saved=p.getInt("audio_pos:"+audioBrowseWorkflow+":"+index,0);mp.seekTo(Math.min(saved,Math.max(0,mp.getDuration()-1000)));applyAudioSpeed();mp.start();audioSeek.setMax(mp.getDuration());startSeekUpdates();});player.setOnCompletionListener(mp->{p.edit().remove("audio_pos:"+audioBrowseWorkflow+":"+index).apply();});player.prepareAsync();}catch(Exception e){add("تعذر تشغيل المقطع: "+e.getMessage());stopAudio();}}
 void startSeekUpdates(){playerHandler.postDelayed(new Runnable(){public void run(){if(player!=null&&player.isPlaying()){if(!seekInProgress)audioSeek.setProgress(player.getCurrentPosition());p.edit().putInt("audio_pos:"+audioBrowseWorkflow+":"+activeTrack,player.getCurrentPosition()).apply();playerHandler.postDelayed(this,500);}}},0);}
 void toggleAudio(){if(player==null){playTrack(selectedAudioIndex());return;}try{if(player.isPlaying()){player.pause();p.edit().putInt("audio_pos:"+audioBrowseWorkflow+":"+activeTrack,player.getCurrentPosition()).apply();}else{applyAudioSpeed();player.start();startSeekUpdates();}}catch(Exception e){add("تعذر التحكم في الصوت: "+e.getMessage());}}
 void stopAudio(){if(player!=null){try{if(activeTrack>=0&&player.getCurrentPosition()>0)p.edit().putInt("audio_pos:"+audioBrowseWorkflow+":"+activeTrack,player.getCurrentPosition()).apply();player.stop();}catch(Exception ignored){}try{player.release();}catch(Exception ignored){}player=null;}}
