 void enqueueDownload(String path,String name){android.app.DownloadManager.Request r=new android.app.DownloadManager.Request(Uri.parse(base()+path));r.setTitle(name);r.setDescription("تنزيل ملف صوت Book2Course");r.setNotificationVisibility(android.app.DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);String token=apiToken();if(!token.isEmpty())r.addRequestHeader("Authorization","Bearer "+token);r.setDestinationInExternalPublicDir(android.os.Environment.DIRECTORY_DOWNLOADS,name);((android.app.DownloadManager)getSystemService(DOWNLOAD_SERVICE)).enqueue(r);add("بدأ تنزيل "+name+" إلى مجلد Downloads");} void previewSelectedStage(){
  progressWatching=true;
  int i=resultStage==null?0:resultStage.getSelectedItemPosition();if(i==0){previewText();return;}if(i==2){showQuestionsByLesson();return;}
  String id=new String[]{ingest,index,qa,translation,audio}[i];String[] routes={"/v1/ingestions/","/v1/indexings/","/v1/course-qa/","/v1/translations/","/v1/audio/"};
  if(id.isEmpty()){add("لم تُسجل نتيجة لهذه المرحلة بعد.");return;}
  runRead("معاينة ناتج المرحلة",()->{JSONObject j;
   if(i==1)j=get(routes[i]+id+"/chunks");
   else if(i==4)j=get(routes[i]+id+"/manifest");
   else {j=get(routes[i]+id);if(!"COMPLETED".equals(j.optString("status"))){if(i==2||i==3)j=get(routes[i]+id+"/checkpoints");else throw new IOException("لا توجد أجزاء مكتملة قابلة للعرض بعد.");}
    if(i==2&&j.has("course_qa"))j=j.getJSONObject("course_qa");if(i==3&&j.has("translation"))j=j.getJSONObject("translation");}
   String value;if(i==1){JSONArray chunks=j.optJSONArray("chunks");StringBuilder content=new StringBuilder("المقاطع المفهرسة: ").append(j.optInt("chunk_count",chunks==null?0:chunks.length())).append("\n\n");if(chunks!=null)for(int n=0;n<chunks.length();n++){JSONObject part=chunks.getJSONObject(n);content.append("مقطع ").append(n+1).append(" · الكتاب: ").append(part.optString("book_id")).append("\n");if(part.has("pages"))content.append("الصفحات: ").append(part.opt("pages")).append("\n");content.append(part.optString("text",part.optString("content",""))).append("\n\n");}value=content.toString();}else value=j.toString(2);if(value.length()>120000)value=value.substring(0,120000)+"\n… عُرض أول 120 ألف حرف لتجنب استهلاك ذاكرة الهاتف؛ استخدم التنزيل للملف الكامل.";
   final String shown=value;runOnUiThread(()->{TextView t=text(shown,14,ink,false);t.setTextIsSelectable(true);ScrollView sc=new ScrollView(this);sc.addView(t);AlertDialog viewer=new AlertDialog.Builder(this).setTitle("محتوى المرحلة / الأجزاء المحفوظة").setView(sc).setPositiveButton("إغلاق",null).create();viewer.show();viewer.getWindow().setLayout(-1,(int)(getResources().getDisplayMetrics().heightPixels*0.90));});return "تم عرض الناتج المحفوظ.";});
 }

 String batchSummary(){try{JSONArray a=new JSONArray(p.getString("qa_lesson_ids","[]"));return a.length()==0?"النطاق: كل الدروس":"النطاق المحدد: "+a.length()+" درسًا";}catch(Exception e){return "النطاق: كل الدروس";}}
