   String courseId=course.getText().toString().trim(),bookId=book.getText().toString().trim();if(!courseId.isEmpty()&&!bookId.isEmpty()){try{JSONObject progress=get("/v1/courses/"+URLEncoder.encode(courseId,"UTF-8")+"/books/"+URLEncoder.encode(bookId,"UTF-8")+"/progress");JSONObject stages=progress.optJSONObject("stages");JSONObject qaStage=stages==null?null:stages.optJSONObject("qa");String currentId=qaStage==null?"":qaStage.optString("workflow_id");if(!currentId.isEmpty()&&!ids.contains(currentId))ids.add(0,currentId);}catch(Exception ignored){}}
