  plan.setText(v+"\n\u0627\u0644\u062e\u0627\u062f\u0645 \u064a\u062a\u062d\u0642\u0642 \u0645\u0646 \u0644\u063a\u0629 \u0627\u0644\u0645\u0635\u062f\u0631 \u0628\u0639\u062f OCR\u060c \u0648\u064a\u062a\u062e\u0637\u0649 \u0627\u0644\u062a\u0631\u062c\u0645\u0629 \u0639\u0646\u062f \u062a\u0637\u0627\u0628\u0642 \u0627\u0644\u0644\u063a\u0629.");
