 void add(String s){String old=log==null?p.getString("log",""):log.getText().toString();String v=old+"["+new SimpleDateFormat("HH:mm:ss",Locale.US).format(new Date())+"] "+s+"\n";if(log!=null)log.setText(v);p.edit().putString("log",v.length()>10000?v.substring(v.length()-10000):v).apply();}
 
 void runRead(String name,Callable<String> task){add("بدء "+name);monitorIo.execute(()->{try{String result=task.call();runOnUiThread(()->add(name+" · "+result));}catch(Exception e){showActionMessage("تعذر "+name,e.getMessage()==null?"تعذر جلب الحالة":e.getMessage());}});}
 void saveBookName(){
  if(selectedBook==null||newPdfSelected){showActionMessage("اختيار كتاب","اختر كتابًا محفوظًا من المكتبة أولًا؛ عنوان PDF الجديد يُحفظ عند رفعه.");return;}
  final String cid=selectedBook.optString("source_course_id",selectedBook.optString("course_id")),bid=selectedBook.optString("book_id"),name=title.getText().toString().trim();
  if(name.isEmpty()){showActionMessage("اسم الكتاب","اكتب اسمًا للكتاب في خانة عنوان الكتاب.");return;}
  run("حفظ اسم الكتاب",()->{JSONObject response=req("PUT","/v1/courses/"+URLEncoder.encode(cid,"UTF-8")+"/books/"+URLEncoder.encode(bid,"UTF-8")+"/name",new JSONObject().put("name",name));runOnUiThread(()->{try{if(selectedBook!=null&&bid.equals(selectedBook.optString("book_id"))){selectedBook.put("title",response.optString("name"));selectedBook.put("display_name",response.optString("name"));title.setText(response.optString("name"));p.edit().putString("title",response.optString("name")).apply();}}catch(JSONException e){add(e.getMessage());}});return "تم حفظ اسم الكتاب؛ بصمته ومراحله لم تتغير.";});
 }
 void loadSavedAudioTracks(){renderScreen(3);runRead("الصوت المحفوظ سابقًا",()->{
  resolveLegacyBookIdentity();final String cid=course.getText().toString().trim(),bid=book.getText().toString().trim();
  JSONObject library=get("/v1/courses/"+URLEncoder.encode(cid,"UTF-8")+"/books/"+URLEncoder.encode(bid,"UTF-8")+"/saved-audio");
  JSONArray tracks=library.optJSONArray("tracks");ArrayList<JSONObject> entries=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();
  if(tracks!=null)for(int n=0;n<tracks.length();n++){JSONObject item=tracks.getJSONObject(n);item.put("_language",item.optString("language"));item.put("_source_identity",item.optJSONObject("source_identity"));item.put("_source_kind","lesson_attachment".equals(item.optString("kind"))?"course":"book");entries.add(item);labels.add("محفوظ سابقًا · "+item.optString("title")+" · "+item.optString("kind"));}
  final String message="ملفات محفوظة مرتبطة ببصمة هذا الكتاب: "+entries.size()+"؛ هذه مخرجات تشغيل سابق للمقارنة وليست تقدم التوليد الحالي.";
  if(entries.isEmpty())labels.add("لا توجد ملفات صوت محفوظة مرتبطة ببصمة هذا الكتاب.");
  runOnUiThread(()->{if(!BookIdentity.sameContext(cid,bid,course.getText().toString().trim(),book.getText().toString().trim()))return;clearAudioSelection();audioBrowseWorkflow="saved:"+cid+":"+bid;audioEntries.addAll(entries);audioSelection.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,labels));});
  return message;
 });}

 boolean schemaFieldAvailable(String name,String field){JSONObject schema=serverCapabilities;if(schema==null)return true;JSONObject components=schema.optJSONObject("components");JSONObject definitions=components==null?null:components.optJSONObject("schemas");JSONObject definition=definitions==null?null:definitions.optJSONObject(name);JSONObject props=definition==null?null:definition.optJSONObject("properties");return props!=null&&props.has(field);}
 boolean serverRouteAvailable(String path,String method){JSONObject schema=serverCapabilities;if(schema==null)return false;JSONObject paths=schema.optJSONObject("paths");JSONObject route=paths==null?null:paths.optJSONObject(path);return route!=null&&route.has(method.toLowerCase(Locale.ROOT));}
 void refreshServerCapabilitiesBlocking()throws Exception{if(serverCapabilities!=null&&System.currentTimeMillis()-serverCapabilitiesAt<30000)return;JSONObject schema=get("/openapi.json");if(schema.optJSONObject("paths")==null)throw new IOException("تعذر التحقق من قدرات الخادم؛ لم نرسل طلب معالجة.");serverCapabilities=schema;serverCapabilitiesAt=System.currentTimeMillis();runOnUiThread(()->{boolean summaries=schemaFieldAvailable("CourseQAGenerationRequest","include_lesson_summaries"),exams=schemaFieldAvailable("CourseQAGenerationRequest","review_assessment_scopes");if(summaryToggle!=null){summaryToggle.setEnabled(summaries);if(!summaries){summaryToggle.setChecked(false);summaryToggle.setText("الملخص المستقل يتطلب تحديث عامل الأسئلة؛ الإثراء الحالي وفق مسار الخادم");}}if(assessmentToggle!=null){assessmentToggle.setEnabled(exams);if(!exams){assessmentToggle.setChecked(false);assessmentToggle.setText("اختيار الميدتيرم والتيرم يتطلب تحديث عامل الأسئلة؛ مراجعة الدروس الحالية متاحة");}}});}
 void applySavedAudioFolder(String cid,JSONObject folder){if(!cid.equals(course.getText().toString().trim()))return;JSONArray tracks=folder.optJSONArray("tracks");clearAudioSelection();audioBrowseWorkflow="saved-course:"+cid;ArrayList<String> names=new ArrayList<>();if(tracks!=null)for(int i=0;i<tracks.length();i++){JSONObject track=tracks.optJSONObject(i);if(track==null)continue;audioEntries.add(track);names.add(track.optString("book_title","")+" · "+track.optString("title",track.optString("filename"))+" · "+track.optString("kind"));}audioSelection.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));audioListStatus.setText("المقرر: "+cid+" · ملفات محفوظة: "+audioEntries.size()+" · يمكنك عرضها وتنزيل كل ملف؛ التوليد الحالي محفوظ بهويته.");}
